    @{ Name = 'editor_mcp_session_checks'; Sources = @('tests/editor_mcp_session_checks.cpp', 'engine/services/McpCommandBridge.cpp', 'engine/assets/AssetRegistry.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'git_index_checks'; Sources = @('tests/git_index_checks.cpp', 'engine/services/GitWorkspace.cpp') },
    @{ Name = 'git_commit_checks'; Sources = @('tests/git_commit_checks.cpp', 'engine/services/GitWorkspace.cpp') },
    @{ Name = 'git_diff_checks'; Sources = @('tests/git_diff_checks.cpp', 'engine/services/GitWorkspace.cpp') },
    @{ Name = 'git_history_checks'; Sources = @('tests/git_history_checks.cpp', 'engine/services/GitWorkspace.cpp') },
    @{ Name = 'git_workspace_checks'; Sources = @('tests/git_workspace_checks.cpp', 'engine/services/GitWorkspace.cpp') },
    @{ Name = 'export_job_checks'; Sources = @('tests/export_job_checks.cpp') },
    @{ Name = 'launcher_recent_checks'; Sources = @('tests/launcher_recent_checks.cpp', 'engine/base/ProjectContext.cpp', 'externals/imgui_node_editor/crude_json.cpp'); Libraries = @('User32.lib', 'Comdlg32.lib', '/SUBSYSTEM:CONSOLE'); Includes = @('/Iengine/base') },
    @{ Name = 'world_playback_checks'; Sources = @('tests/world_playback_checks.cpp', 'engine/script/ScriptRuntime.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'project_creation_checks'; Sources = @('tests/project_creation_checks.cpp', 'engine/base/ProjectContext.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'gamepad_action_map_checks'; Sources = @('tests/gamepad_action_map_checks.cpp', 'engine/input/ActionMap.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'gamepad_frame_checks'; Sources = @('tests/gamepad_frame_checks.cpp') },
    @{ Name = 'action_map_persistence_checks'; Sources = @('tests/action_map_persistence_checks.cpp', 'engine/input/ActionMap.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'scene_history_checks'; Sources = @('tests/scene_history_checks.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'scene_document_checks'; Sources = @('tests/scene_document_checks.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'engine_model_asset_checks'; Sources = @('tests/engine_model_asset_checks.cpp', 'engine/3d/model/ModelAssetResolver.cpp') },
    @{ Name = 'logger_checks'; Sources = @('tests/logger_checks.cpp', 'engine/base/utility/Logger.cpp') },
    @{ Name = 'animation_time_checks'; Sources = @('tests/animation_time_checks.cpp', 'engine/scene/core/SceneManager.cpp') },
    @{ Name = 'input_action_map_checks'; Sources = @('tests/input_action_map_checks.cpp', 'engine/input/ActionMap.cpp', 'externals/imgui_node_editor/crude_json.cpp') }
    @{ Name = 'entity_world_checks'; Sources = @('tests/entity_world_checks.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') }
    @{ Name = 'asset_registry_checks'; Sources = @('tests/asset_registry_checks.cpp', 'engine/assets/AssetRegistry.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'physics_world_checks'; Sources = @('tests/physics_world_checks.cpp', 'engine/physics/PhysicsWorld.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'script_runtime_checks'; Sources = @('tests/script_runtime_checks.cpp', 'engine/script/ScriptRuntime.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') },
    @{ Name = 'services_checks'; Sources = @('tests/services_checks.cpp', 'engine/services/GitWorkspace.cpp', 'engine/services/UpdateService.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp'); Libraries = @('bcrypt.lib') },
    @{ Name = 'mcp_bridge_checks'; Sources = @('tests/mcp_bridge_checks.cpp', 'engine/services/McpCommandBridge.cpp', 'engine/assets/AssetRegistry.cpp', 'engine/scene/entity/EntityWorld.cpp', 'engine/scene/core/SceneDocument.cpp', 'externals/imgui_node_editor/crude_json.cpp') }
)
if($Only -and !@($checks | Where-Object {$_.Name -eq $Only}).Count) {
    throw "Unknown CPU suite '$Only'; -Only requires one exact registered name"
}
Push-Location $project
try {
    $luaChecks = @($checks | Where-Object { (!$Only -or $_.Name -eq $Only) -and $_.Sources -contains 'engine/script/ScriptRuntime.cpp' })
    if ($luaChecks.Count -gt 0) {
        $luaOutput = Join-Path $output 'lua'
        New-Item -ItemType Directory -Force -Path $luaOutput | Out-Null
        $luaSources = @(Get-ChildItem -LiteralPath 'externals/lua-5.4.9/src' -Filter '*.c' | Where-Object { $_.Name -notin @('lua.c','luac.c') } | ForEach-Object { $_.FullName })
        & cl.exe /nologo /TC /MT /O2 /W3 /D_CRT_SECURE_NO_WARNINGS /c @luaSources "/Fo:$luaOutput/"
        if ($LASTEXITCODE -ne 0) { throw 'Lua library compilation failed' }
        $luaObjects = @(Get-ChildItem -LiteralPath $luaOutput -Filter '*.obj' | ForEach-Object { $_.FullName })
        & lib.exe /nologo "/OUT:$luaOutput/KuboLua.lib" @luaObjects
        if ($LASTEXITCODE -ne 0) { throw 'Lua static library creation failed' }
    }
    $cpuChecksExecuted = 0
    foreach ($check in $checks) {
        if ($Only -and $check.Name -ne $Only) { continue }
        Write-Output "CPU_CHECK_START=$($check.Name)"
        $exe = Join-Path $output ($check.Name + '.exe')
        $linkOptions = @()
        $extraIncludes = @()
        if ($check.ContainsKey('Includes')) { $extraIncludes = @($check.Includes) }
        if ($check.ContainsKey('Libraries')) { $linkOptions = @('/link') + @($check.Libraries) }
        $checkSources = @($check.Sources)
        if ($check.Name -in @('hub_workspace_checks','hub_package_installation_checks','hub_package_verification_checks','hub_engine_identity_checks','launcher_recent_checks')) {
            $checkSources += 'engine/services/UpdateService.cpp'
            $checkSources += 'engine/services/GitWorkspace.cpp'
        }
        if(($checkSources -contains 'engine/scene/entity/EntityWorld.cpp' -or $checkSources -contains 'engine/assets/AssetSceneDependencies.cpp' -or $checkSources -contains 'engine/scene/entity/RenderParticleFrame.cpp') -and $checkSources -notcontains 'engine/scene/entity/ParticleComponents.cpp') { $checkSources += 'engine/scene/entity/ParticleComponents.cpp' }
        if ($checkSources -contains 'engine/script/ScriptRuntime.cpp') {
            if ($checkSources -notcontains 'engine/physics/PhysicsWorld.cpp') { $checkSources += 'engine/physics/PhysicsWorld.cpp' }
            $checkSources += 'engine/script/LuaScript.cpp'
            if ($checkSources -notcontains 'engine/assets/AssetRegistry.cpp') { $checkSources += 'engine/assets/AssetRegistry.cpp' }
            if ($linkOptions.Count -eq 0) { $linkOptions = @('/link') }
            if ($linkOptions -notcontains 'bcrypt.lib') { $linkOptions += 'bcrypt.lib' }
            $linkOptions += (Join-Path $luaOutput 'KuboLua.lib')
        }
        & cl.exe /nologo /std:c++20 /EHsc /utf-8 /W3 /WX /I. /Iengine/math/types /Iengine/scene/core /Iexternals/imgui_node_editor @extraIncludes @checkSources "/Fe:$exe" "/Fo:$output/" @linkOptions
        if ($LASTEXITCODE -ne 0) { throw "$($check.Name) compilation failed" }
        & $exe
        if ($LASTEXITCODE -ne 0) { throw "$($check.Name) failed" }
        $cpuChecksExecuted++
        Write-Output "CPU_CHECK_PASS=$($check.Name)"
    }
    Write-Output "CPU_CHECK_SUMMARY=$cpuChecksExecuted REGISTERED=$($checks.Count)"
} finally {
    Pop-Location
}
